};
const ledger = () => document.querySelector('[data-testid="qs-item-binding-ledger"]');
const statuses = (el) => [...el.querySelectorAll('[data-binding-status]')].map(r => r.getAttribute('data-binding-status'));
const notice = (el) => el.querySelector('[data-testid="qs-binding-withheld-notice"]');
const pricing = (el, id) => el.querySelector('[data-testid="qs-binding-pricing-' + id + '"]');
const focusTop = (s) => { const el = document.querySelector(s); if (!el) throw Error('Nothing to show for ' + s); el.scrollIntoView({ block: 'start' }); return 'framed ' + s; };
  const el = ledger();
  if (!el) throw Error('No item binding ledger rendered');
  const rows = statuses(el);
  if (rows.length !== 3) throw Error('Expected 3 binding rows, got ' + rows.length);
  if (rows.some(s => s !== 'unbound')) throw Error('Unbound draft reported a non-unbound status: ' + rows.join(','));
  const banner = notice(el);
  if (!banner) throw Error('Withheld notice missing on a fully unbound draft');
  if (!banner.textContent.includes('Pricing withheld on 3 items')) throw Error('Banner count wrong: ' + banner.textContent.slice(0, 200));
  if (!banner.textContent.includes('3 unbound')) throw Error('Banner does not tally unbound items: ' + banner.textContent.slice(0, 200));
  if (!pricing(el, 'Bulk Trench Excavation').textContent.includes('Withheld')) throw Error('Unbound item did not withhold pricing');
  if (el.textContent.includes('VERIFIED')) throw Error('Unbound draft rendered a verified badge');
  return 'Unbound: 3 rows unbound, notice present, all pricing withheld';
})()

