  if (!el) throw Error('No ledger after the edit');
  const rows = statuses(el);
  if (rows.includes('unbound')) throw Error('Ledger still reports the edited item as unbound: ' + rows.join(','));
  const row = el.querySelector('[data-testid="qs-binding-row-Bulk%20Trench%20Excavation"]');
  if (!row) throw Error('No ledger row for item-exc');
  if (row.getAttribute('data-binding-status') !== 'stale-measurement')
    throw Error('Edited item is not stale-measurement: ' + row.getAttribute('data-binding-status'));
